    private void voiceSettings(){body.addView(title("Kết nối THT Voice"));toggle("Cho phép nhận lệnh từ THT Voice","voice_enabled",false);note("THT Split chỉ nhận lệnh chia màn hình. Popup, micro, vị trí và thời gian tự tắt do THT Voice quản lý; không dành diện tích cố định.");note("API v2 có phản hồi. Voice cùng chữ ký có thể dùng SignatureVoiceReceiver không cần token; khác chữ ký dùng token được lưu qua reboot. Repo Voice cần tích hợp theo tài liệu.");button(body,"Xem / sao chép token kết nối",false,()->showSecret("voice_token","Token THT Voice"));button(body,"Đổi token Voice",false,()->new AlertDialog.Builder(this).setTitle("Đổi token?").setMessage("THT Voice cần nhập token mới để tiếp tục điều khiển.").setPositiveButton("Đổi",(d,n)->{store.set("voice_token",Store.randomToken());toast("Đã đổi token");}).setNegativeButton("Hủy",null).show());button(body,"Tài liệu lệnh Voice",false,()->openUrl("https://github.com/meomeo2099/THT-Split/blob/main/docs/VOICE_API.md"));}
